import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        int n = scanner.nextInt();
        int h = scanner.nextInt();

        int[][] memo = new int[n + 1][n + 1];
        for (int i = 0; i <= n; i++) {
            for (int j = 0; j <= n; j++) {
                memo[i][j] = -1;
            }
        }
        memo[0][0] = 1;

        System.out.println(recursiveCount(n, h, memo));
        scanner.close();
    }

    private static int recursiveCount(int n, int h, int[][] memo) {
        if (memo[n][h] != -1) {
            return memo[n][h];
        }
        if (n == 0) {
            return 0;
        }
        if (h == 0) {
            return recursiveCount(n, 1, memo);
        }

        int result = 0;
        for (int i = 0; i < n; i++) {
            result += recursiveCount(n - i - 1, 0, memo) * recursiveCount(i, h - 1, memo);
            result += recursiveCount(n - i - 1, h - 1, memo) * recursiveCount(i, 0, memo);
            result -= recursiveCount(n - i - 1, h - 1, memo) * recursiveCount(i, h - 1, memo);
        }

        memo[n][h] = result;
        return result;
    }
}
